package com.dentalclinic.treatment.service;
import com.dentalclinic.treatment.dto.*;import com.dentalclinic.treatment.entity.*;import com.dentalclinic.treatment.repository.*;
import com.dentalclinic.clinic.service.TenantClinicResolver;import com.dentalclinic.security.util.SecurityUtils;import com.dentalclinic.user.entity.AppUser;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.data.domain.*;import lombok.RequiredArgsConstructor;
import java.util.*;import java.math.*;import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class TreatmentPlanItemService {
 private final TenantClinicResolver clinics;private final TreatmentPlanRepository plans;private final TreatmentPlanItemRepository items;private final TreatmentPlanService totals;private final TreatmentItemAudit audit;private final TreatmentPlanItemAuditRepository history;private final JdbcTemplate jdbc;
 public static long version(String match){if(match==null)throw new TreatmentItemException(428,"If-Match version is required");if(!match.matches("\"[0-9]+\""))throw new TreatmentItemException(400,"If-Match must be one quoted nonnegative version");try{return Long.parseLong(match.substring(1,match.length()-1));}catch(NumberFormatException e){throw new TreatmentItemException(400,"Invalid If-Match version");}}
 private TreatmentPlan parent(UUID id,UUID requested,AppUser actor){var clinic=clinics.resolve(actor,requested,"clinicId is required");var plan=plans.lockByIdAndClinicId(id,clinic.getId()).orElseThrow(()->new TreatmentItemException(404,"Treatment plan not found"));TreatmentPlanRemovalService.requireActive(plan);if(plan.getStatus()!=TreatmentPlanStatus.DRAFT)throw new TreatmentItemException(409,"Only DRAFT treatment plans can be changed");return plan;}
 private TreatmentPlanItem item(TreatmentPlan p,UUID id,long expected){var item=items.findByIdAndClinicIdWithDetails(id,p.getClinic().getId()).filter(i->i.getTreatmentPlan().getId().equals(p.getId())&&i.getClinic().getId().equals(p.getClinic().getId())).orElseThrow(()->new TreatmentItemException(404,"Treatment plan item not found"));if(item.getRemovedAt()!=null)throw new TreatmentItemException(409,"Item has already been removed");if(item.getVersion()!=expected)throw new TreatmentItemException(412,"Item changed; reload before trying again");
 if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from invoice_item where treatment_plan_item_id=? union all select 1 from patient_material_usage where treatment_plan_item_id=? union all select 1 from patient_follow_up where treatment_plan_item_id=? union all select 1 from patient_consent where treatment_plan_item_id=?)",Boolean.class,id,id,id,id)))throw new TreatmentItemException(409,"Item has downstream references and cannot be changed");return item;}
 private static String text(String v){return v==null||v.isBlank()?null:v.trim();}
 @Transactional public TreatmentPlanItemResponse update(UUID planId,UUID itemId,UUID clinicId,String match,UpdateTreatmentPlanItemRequest r){
 long expected=version(match);if(r==null||r.getQuantity()==null||r.getQuantity()<1||r.getEstimatedVisits()!=null&&r.getEstimatedVisits()<1)throw new TreatmentItemException(400,"Quantity and estimated visits must be positive");String tooth=text(r.getToothNumber());if(tooth!=null&&tooth.codePointCount(0,tooth.length())>10)throw new TreatmentItemException(400,"Tooth number must not exceed 10 characters");
 var actor=SecurityUtils.getCurrentUser();var p=parent(planId,clinicId,actor);var i=item(p,itemId,expected);var before=TreatmentItemAudit.snapshot(i);
 if(!i.getQuantity().equals(r.getQuantity())){
 if(i.getDiscountValue().signum()!=0||i.getDiscountAmount().signum()!=0||i.getFinalAmount().compareTo(i.getGrossAmount())!=0)throw new TreatmentItemException(409,"Quantity changes with legacy item discounts are unsupported");
 var gross=i.getUnitPrice().multiply(BigDecimal.valueOf(r.getQuantity())).setScale(2,RoundingMode.HALF_UP);if(gross.precision()>12)throw new TreatmentItemException(400,"Item amount exceeds supported precision");i.setGrossAmount(gross);i.setFinalAmount(gross);
 }
 i.setQuantity(r.getQuantity());i.setToothNumber(tooth);i.setEstimatedVisits(r.getEstimatedVisits());i.setDescription(text(r.getDescription()));i.setClinicalNotes(text(r.getClinicalNotes()));i.setPatientExplanation(text(r.getPatientExplanation()));i.setFollowUpInstructions(text(r.getFollowUpInstructions()));i.setUpdatedBy(actor);i.setUpdatedAt(LocalDateTime.now());items.saveAndFlush(i);totals.recalculateTreatmentPlan(p,actor);audit.write(i,actor,"UPDATE",before,null);return totals.mapItemResponse(i);
 }
 @Transactional public void remove(UUID planId,UUID itemId,UUID clinicId,String match,RemoveTreatmentPlanItemRequest r){long expected=version(match);if(r==null||!com.dentalclinic.casesheet.validation.RemovalReasonValidator.valid(r.getReason()))throw new TreatmentItemException(400,"Invalid removal reason");var actor=SecurityUtils.getCurrentUser();var p=parent(planId,clinicId,actor);var i=item(p,itemId,expected);var before=TreatmentItemAudit.snapshot(i);i.setRemovedAt(LocalDateTime.now());i.setRemovedBy(actor);i.setUpdatedBy(actor);items.saveAndFlush(i);totals.recalculateTreatmentPlan(p,actor);audit.write(i,actor,"REMOVE",before,r.getReason());}
 public record Event(UUID id,UUID itemId,String operation,UUID actorId,LocalDateTime timestamp,Map<String,Object> before,Map<String,Object> after,String removalReason){}
 public record HistoryPage(List<Event> content,int number,int size,long totalElements,int totalPages){}
 @Transactional(readOnly=true) public HistoryPage history(UUID planId,UUID requested,int page,int size){if(page<0||size<1||(long)page*Math.min(size,100)>Integer.MAX_VALUE)throw new TreatmentItemException(400,"Invalid page or size");var clinic=clinics.resolve(SecurityUtils.getCurrentUser(),requested,"clinicId is required");plans.findByIdAndClinicId(planId,clinic.getId()).orElseThrow(()->new TreatmentItemException(404,"Treatment plan not found"));var result=history.findByClinicIdAndTreatmentPlanId(clinic.getId(),planId,PageRequest.of(page,Math.min(size,100),Sort.by(Sort.Direction.DESC,"createdAt","id")));return new HistoryPage(result.map(a->new Event(a.getId(),a.getItemId(),a.getOperation(),a.getActorId(),a.getCreatedAt(),a.getBeforeSnapshot(),a.getAfterSnapshot(),a.getRemovalReason())).getContent(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages());}
}
